#!/usr/bin/env bash
# =============================================================================
# AlphaCP — D12 PHPMYADMIN + ONE-CLICK SSO v1.0  (live panel 0.75.x + paneld · 09 Oct 2026)
#
# Phase-2 Wave D12: asli phpMyAdmin (apt) + cPanel-style one-click login.
#   APP:   apt phpmyadmin (dbconfig off) — fail => clean abort, kuch nahi badla
#   AGENT: db.pmaSignon task (pma_<account> rotate, grants sirf apne DBs)
#   PANEL: Open phpMyAdmin button -> one-time 10-min token -> :2098 shim -> login
#   PMA:   signon config + nginx vhost 2098 (nginx -t gate) + ufw + secrets
# 9 files, multi-root. DB me KOI migration nahi (token = encrypted file, 10 min).
# Safety: backup (.bak-d12pma-<stamp>) -> install -> caches -> paneld gate ->
#   nginx gate -> health (3 ports + :2098) -> AUTO-ROLLBACK.
# =============================================================================
set -Eeuo pipefail

D12_VERSION="1.0"

PANEL_ROOT="${PANEL_ROOT:-/usr/local/alphacp/panel}"
AGENT_ROOT="${AGENT_ROOT:-/usr/local/alphacp/agent}"
ACP_ETC="${ACP_ETC:-/usr/local/alphacp/etc}"
NGX_AVAIL="${NGX_AVAIL:-/etc/nginx/sites-available}"
NGX_ENABLED="${NGX_ENABLED:-/etc/nginx/sites-enabled}"
PMA_ROOT="${PMA_ROOT:-/usr/share/phpmyadmin}"
PMA_ETC="${PMA_ETC:-/etc/phpmyadmin}"
STAMP="$(date -u +%Y%m%d%H%M%S)"
LOG_FILE="/var/log/alphacp-d12-phpmyadmin-sso.log"

C_B=$'\033[1m'; C_G=$'\033[32m'; C_R=$'\033[31m'; C_Y=$'\033[33m'; C_0=$'\033[0m'
say() { printf '%s\n' "$*"; }
log() { printf '%s [%s]\n' "$(date -u '+%F %T')Z" "$*" >>"${LOG_FILE}" 2>/dev/null || true; }
ok()  { log "OK   $*"; say "${C_G}[OK]${C_0} $*"; }
warn(){ log "WARN $*"; say "${C_Y}[!]${C_0} $*"; }
die() { log "FAIL $*"; say "${C_R}[x]${C_0} $*"; say "Log: ${LOG_FILE}"; exit 1; }

say ""
say "${C_B}== AlphaCP D12 PHPMYADMIN + SSO v${D12_VERSION} ==${C_0}"
[[ "${EUID}" -eq 0 ]] || die "root chahiye: sudo bash $0"
[[ -d "${PANEL_ROOT}/public/assets" ]] || die "panel nahi mila: ${PANEL_ROOT}"
[[ -f "${PANEL_ROOT}/public/assets/panel.js" ]] || die "pehle theme-fix v1.2 install karo (panel.js missing) — COMMANDS.md dekho"
[[ -f "${AGENT_ROOT}/config/tasks.php" ]] || die "agent nahi mila: ${AGENT_ROOT} (pehle D11 wave install karo)"
grep -q "service.restart" "${AGENT_ROOT}/config/tasks.php" || die "agent tasks.php me D11 (service.restart) nahi — pehle D11 wave install karo"

F0_PATH="AGENT:config/tasks.php"
