resolve_dst() {
  local rel="$1"
  case "${rel}" in
    AGENT:*)  printf '%s/%s' "${AGENT_ROOT}" "${rel#AGENT:}" ;;
    PMA:*)    printf '%s/%s' "${PMA_ROOT}"   "${rel#PMA:}" ;;
    PMAETC:*) printf '%s/%s' "${PMA_ETC}"    "${rel#PMAETC:}" ;;
    NGX:*)    printf '%s/%s' "${NGX_AVAIL}"  "${rel#NGX:}" ;;
    PANEL:*)  printf '%s/%s' "${PANEL_ROOT}" "${rel#PANEL:}" ;;
    *)        printf '%s/%s' "${PANEL_ROOT}" "${rel}" ;;
  esac
}

install_one() {
  local rel="$1" sha="$2" b64="$3"
  local dst; dst="$(resolve_dst "${rel}")"
  local is_new=0
  [[ -f "${dst}" ]] || is_new=1
  mkdir -p "$(dirname "${dst}")"
  local tmp="${dst}.new-${STAMP}"
  printf '%s' "${b64}" | base64 -d > "${tmp}" || die "decode fail: ${rel}"
  local got; got="$(sha256sum "${tmp}" | awk '{print $1}')"
  [[ "${got}" == "${sha}" ]] || { rm -f "${tmp}"; die "sha256 mismatch: ${rel} (${got})"; }
  if [[ "${is_new}" -eq 0 ]]; then
    cp -a "${dst}" "${dst}.bak-d12pma-${STAMP}"
    chown --reference="${dst}" "${tmp}" 2>/dev/null || true
    chmod --reference="${dst}" "${tmp}" 2>/dev/null || true
  else
    case "${rel}" in
      PANEL:*) chown --reference="${PANEL_ROOT}/public/assets/panel.css" "${tmp}" 2>/dev/null || true ;;
      *)       chown root:root "${tmp}" 2>/dev/null || true ;;
    esac
    chmod 0644 "${tmp}" 2>/dev/null || true
  fi
  mv -f "${tmp}" "${dst}"
  if [[ "${is_new}" -eq 0 ]]; then
    ok "installed: ${rel}  (backup: $(basename "${dst}").bak-d12pma-${STAMP})"
  else
    ok "installed (NEW): ${rel}"
  fi
}

rollback() {
  warn "ROLLBACK shuru..."
  local rel dst
  for rel in "${F0_PATH}" "${F1_PATH}" "${F2_PATH}" "${F3_PATH}" "${F4_PATH}" "${F5_PATH}" "${F6_PATH}" "${F7_PATH}" "${F8_PATH}"; do
    dst="$(resolve_dst "${rel}")"
    if [[ -f "${dst}.bak-d12pma-${STAMP}" ]]; then
      mv -f "${dst}.bak-d12pma-${STAMP}" "${dst}"
      warn "restored: ${rel}"
    fi
  done
  if [[ "${LIVE_SRV:-0}" -eq 1 && "${VHOST_ENABLED_BY_US:-0}" -eq 1 ]]; then
    rm -f "${NGX_ENABLED}/alphacp-pma.conf"
    nginx -t >>"${LOG_FILE}" 2>&1 && systemctl reload nginx >>"${LOG_FILE}" 2>&1 || true
    warn "nginx vhost 2098 disable + reload"
  fi
  clear_caches
  if [[ "${PANELD_WAS_ACTIVE:-0}" -eq 1 ]]; then systemctl restart paneld >>"${LOG_FILE}" 2>&1 || true; fi
  warn "ROLLBACK done — panel + agent pehle jaise."
}

clear_caches() {
  local php=""
  for c in php8.4 php8.3 php; do command -v "$c" >/dev/null 2>&1 && { php="$c"; break; }; done
  [[ -n "${php}" ]] || { warn "php nahi mila — caches manually clear karo"; return 0; }
  local runas=""
  if id alphacp >/dev/null 2>&1; then runas="sudo -u alphacp"; fi
  ( cd "${PANEL_ROOT}" && ${runas} "${php}" artisan view:clear >>"${LOG_FILE}" 2>&1 ) \
    && ok "view cache cleared" || warn "view:clear fail (non-fatal)"
  ( cd "${PANEL_ROOT}" && ${runas} "${php}" artisan route:clear >>"${LOG_FILE}" 2>&1 ) \
    && ok "route cache cleared" || warn "route:clear fail (non-fatal)"
  local fpm
  for fpm in php8.4-fpm php8.3-fpm php-fpm; do
    if systemctl is-active --quiet "${fpm}" 2>/dev/null; then
      systemctl reload "${fpm}" >>"${LOG_FILE}" 2>&1 \
        && ok "${fpm} reloaded (graceful)" || warn "${fpm} reload fail (non-fatal)"
      break
    fi
  done
}

health() {
  local port code bad=0
  for port in 8090 2083 2087; do
    code="$(curl -k -s -o /dev/null -w '%{http_code}' -m 15 "https://127.0.0.1:${port}/" 2>/dev/null || echo 000)"
    if [[ "${code}" == "200" || "${code}" == "302" ]]; then
      ok "health :${port} -> HTTP ${code}"
    else
      warn "health :${port} -> HTTP ${code}"
      bad=1
    fi
  done
  return "${bad}"
}

say ""
say "${C_B}-- Step 1: pre-check --${C_0}"
health || die "panel pehle se unhealthy hai — pehle panel-doctor chalao"
PANELD_WAS_ACTIVE=0
systemctl is-active paneld >/dev/null 2>&1 && PANELD_WAS_ACTIVE=1
if [[ "${PANELD_WAS_ACTIVE}" -eq 1 ]]; then ok "paneld active hai (restart gate ON)"; else warn "paneld systemd active nahi (sim/container?) — agent restart skip hoga"; fi
LIVE_SRV=0
systemctl is-active nginx >/dev/null 2>&1 && LIVE_SRV=1
if [[ "${LIVE_SRV}" -eq 1 ]]; then ok "nginx active (LIVE mode: apt + vhost + ufw chalenge)"; else warn "nginx systemd active nahi (sim?) — apt/vhost/ufw steps skip"; fi
VHOST_ENABLED_BY_US=0

if [[ "${LIVE_SRV}" -eq 1 ]]; then
  say ""
  say "${C_B}-- Step 1b: phpMyAdmin app (apt) --${C_0}"
  if [[ -f "${PMA_ROOT}/index.php" ]]; then
    ok "phpMyAdmin pehle se installed: ${PMA_ROOT}"
  else
    echo 'phpmyadmin phpmyadmin/dbconfig-install boolean false' | debconf-set-selections >>"${LOG_FILE}" 2>&1 || true
    echo 'phpmyadmin phpmyadmin/reconfigure-webserver multiselect ' | debconf-set-selections >>"${LOG_FILE}" 2>&1 || true
    DEBIAN_FRONTEND=noninteractive apt-get install -y phpmyadmin >>"${LOG_FILE}" 2>&1 \
      || die "apt-get install phpmyadmin FAIL — log dekho. (Abhi tak KUCH install nahi hua, panel 100% safe)"
    [[ -f "${PMA_ROOT}/index.php" ]] || die "apt chala par ${PMA_ROOT}/index.php nahi mila"
    ok "phpMyAdmin installed via apt: ${PMA_ROOT}"
  fi
fi

say ""
say "${C_B}-- Step 1c: secrets + pma config glue --${C_0}"
mkdir -p "${ACP_ETC}" "${PMA_ETC}/conf.d"
if [[ ! -f "${ACP_ETC}/pma-sso.secret" ]]; then
  ( umask 027 && openssl rand -hex 32 > "${ACP_ETC}/pma-sso.secret" ) || die "pma-sso.secret generate fail"
  ok "pma-sso.secret generated"
else
  ok "pma-sso.secret pehle se hai (rotate nahi karenge)"
fi
chown root:www-data "${ACP_ETC}/pma-sso.secret" 2>/dev/null || true
chmod 0640 "${ACP_ETC}/pma-sso.secret"
printf 'https://127.0.0.1:2083/internal/pma-sso' > "${ACP_ETC}/pma-sso-internal.url"
chmod 0644 "${ACP_ETC}/pma-sso-internal.url"
ok "pma-sso-internal.url written"
if [[ ! -f "${PMA_ETC}/acp-blowfish.secret" ]]; then
  ( umask 027 && openssl rand -hex 32 > "${PMA_ETC}/acp-blowfish.secret" ) || die "blowfish secret generate fail"
  chown root:www-data "${PMA_ETC}/acp-blowfish.secret" 2>/dev/null || true
  chmod 0640 "${PMA_ETC}/acp-blowfish.secret"
  ok "acp-blowfish.secret generated"
fi
if [[ ! -f "${PMA_ETC}/config-db.php" ]]; then
  printf '<?php\n' > "${PMA_ETC}/config-db.php"
  ok "config-db.php stub (dbconfig off)"
fi
if [[ -f "${PMA_ETC}/config.inc.php" ]]; then
  if grep -q "conf.d" "${PMA_ETC}/config.inc.php"; then
    ok "config.inc.php me conf.d include pehle se hai"
  else
    cp -a "${PMA_ETC}/config.inc.php" "${PMA_ETC}/config.inc.php.bak-d12pma-${STAMP}"
    cat >> "${PMA_ETC}/config.inc.php" <<'ACPCONFD'

/* AlphaCP d12: conf.d drop-ins load karo */
foreach (glob('/etc/phpmyadmin/conf.d/*.php') as $acpConfD) {
    require $acpConfD;
}
ACPCONFD
    ok "conf.d include added (backup: config.inc.php.bak-d12pma-${STAMP})"
  fi
else
  warn "${PMA_ETC}/config.inc.php nahi mila (sim?) — conf.d include skip"
fi

say ""
say "${C_B}-- Step 2: install (9 files, backup ke saath) --${C_0}"
install_one "${F0_PATH}" "${F0_SHA}" "${F0_B64}"
install_one "${F1_PATH}" "${F1_SHA}" "${F1_B64}"
install_one "${F2_PATH}" "${F2_SHA}" "${F2_B64}"
install_one "${F3_PATH}" "${F3_SHA}" "${F3_B64}"
install_one "${F4_PATH}" "${F4_SHA}" "${F4_B64}"
install_one "${F5_PATH}" "${F5_SHA}" "${F5_B64}"
install_one "${F6_PATH}" "${F6_SHA}" "${F6_B64}"
install_one "${F7_PATH}" "${F7_SHA}" "${F7_B64}"
install_one "${F8_PATH}" "${F8_SHA}" "${F8_B64}"

say ""
say "${C_B}-- Step 3: perms + caches clear + php-fpm reload --${C_0}"
chown root:root "${AGENT_ROOT}/src/Tasks/PmaSignon.php" 2>/dev/null || true
chmod 0644 "${PMA_ROOT}/acp-signon.php" 2>/dev/null || true
chmod 0644 "${PMA_ETC}/conf.d/acp-signon.php" 2>/dev/null || true
mkdir -p "${PANEL_ROOT}/storage/app/pma-sso"
chown --reference="${PANEL_ROOT}/storage/app" "${PANEL_ROOT}/storage/app/pma-sso" 2>/dev/null || true
clear_caches

say ""
say "${C_B}-- Step 3b: paneld restart (agent registry reload) --${C_0}"
if [[ "${PANELD_WAS_ACTIVE}" -eq 1 ]]; then
  if systemctl restart paneld >>"${LOG_FILE}" 2>&1 && sleep 2 && systemctl is-active paneld >/dev/null 2>&1; then
    ok "paneld restarted — db.pmaSignon task ab live"
  else
    warn "paneld restart FAIL — full rollback"
    rollback
    systemctl restart paneld >>"${LOG_FILE}" 2>&1 || true
    die "paneld wapas start nahi hua naye config ke saath — sab files restore (rollback ho gaya)"
  fi
else
  warn "paneld restart skip (systemd active nahi tha)"
fi

if [[ "${LIVE_SRV}" -eq 1 ]]; then
  say ""
  say "${C_B}-- Step 3c: nginx vhost (port 2098) + firewall --${C_0}"
  if [[ ! -e "${NGX_ENABLED}/alphacp-pma.conf" ]]; then
    ln -s "${NGX_AVAIL}/alphacp-pma.conf" "${NGX_ENABLED}/alphacp-pma.conf"
    VHOST_ENABLED_BY_US=1
  fi
  if nginx -t >>"${LOG_FILE}" 2>&1; then
    systemctl reload nginx >>"${LOG_FILE}" 2>&1 && ok "nginx reloaded — phpMyAdmin :2098 live" \
      || { rollback; die "nginx reload fail — rollback ho gaya"; }
  else
    warn "nginx -t FAIL"
    rollback
    die "nginx config test fail — sab wapas purana (rollback ho gaya)"
  fi
  if command -v ufw >/dev/null 2>&1; then
    ufw allow 2098/tcp >>"${LOG_FILE}" 2>&1 && ok "ufw: 2098/tcp allowed" || warn "ufw allow 2098 fail (non-fatal)"
  fi
fi

say ""
say "${C_B}-- Step 4: health check --${C_0}"
if ! health; then
  rollback
  die "health check fail — sab files wapas purani (rollback ho gaya)"
fi
if [[ "${LIVE_SRV}" -eq 1 ]]; then
  code="$(curl -k -s -o /dev/null -w '%{http_code}' -m 15 "https://127.0.0.1:2098/acp-signon.php" 2>/dev/null || echo 000)"
  if [[ "${code}" == "200" ]]; then
    ok "health :2098 (phpMyAdmin SSO shim) -> HTTP ${code}"
  else
    warn "health :2098 -> HTTP ${code}"
    rollback
    die ":2098 shim respond nahi kar raha — rollback ho gaya"
  fi
fi

say ""
say "${C_G}${C_B}==> D12 PHPMYADMIN + SSO COMPLETE ✅${C_0}"
say "    Browser hard-refresh (Ctrl+Shift+R) karke 2083 panel kholo:"
say "      Databases -> phpMyAdmin -> (Enable + Save agar off hai) -> Open phpMyAdmin"
say "      Password NAHI poochega — seedha apne databases dikhega (:2098 par)"
say "      Access sirf apne DBs par (pma_<account> user, har click par password rotate)"
say "      Har open Audit Log me darj hota hai (db.pma.sso)"
say "    Rollback kabhi bhi: *.bak-d12pma-${STAMP} files apni jagah par hain"
say "    — d12-phpmyadmin-sso v${D12_VERSION}"
